llamadas.contenido:
{
  "title": "Historia de Usuario (HU) para reservar un ejemplar de la Biblioteca Municipal de Villaficticia",
  "role": "Persona socia de la Biblioteca Municipal de Villaficticia",
  "action": "Reservar un ejemplar desde la web para recogerlo en el mostrador",
  "benefit": "Acceder a un ejemplar de libro para recoger en el mostrador conforme a las normas establecidas",
  "description": "La persona socia quiere reservar un ejemplar de la Biblioteca Municipal de Villaficticia para recogerlo en el mostrador. El proceso debe estar en conformidad con el Reglamento de reservas (DOC-02) y con las políticas de la Biblioteca.",
  "business_goal": "Facilitar el acceso a ejemplares de libros para personas socias, mediante la reservación en la web y su recogida en el mostrador según las reglas establecidas.",
  "scope_includes": [
    "La reserva se realiza desde la web",
    "El ejemplar se recoge en el mostrador",
    "La persona socia tiene el derecho a cancelar la reserva si es necesario",
    "La reserva tiene un plazo de 48 horas para la recogida",
    "La reserva se gestiona según el Reglamento de reservas (DOC-02)"
  ],
  "scope_excludes": [
    "El acceso a ejemplares para personas no socias",
    "La gestión de préstamos fuera de la Biblioteca",
    "La gestión de devoluciones",
    "La gestión de renovaciones"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Requisito de permiso",
      "given": ["La persona socia debe tener un carné vigente y sin sanción activa (ver RN-SAN-03 y RN-SAN-04 en DOC-03)"],
      "when": ["La solicitud se envía desde la web"],
      "then": ["La reserva se registra y se muestra en la cola de reservas"]
    },
    {
      "id": "CA-02",
      "title": "Requisito de plazo",
      "given": ["La reserva se activa si el ejemplar está disponible en la sede de recogida (ver RN-RES-05)"],
      "when": ["La persona socia solicita la reserva"],
      "then": ["La reserva entra en estado 'Pendiente' en la cola de reservas"]
    },
    {
      "id": "CA-03",
      "title": "Requisito de plazo para recoger",
      "given": ["La persona socia debe recoger el ejemplar dentro de 48 horas (ver RN-RES-05 y RN-RES-06)"],
      "when": ["La reserva se activa"],
      "then": ["La reserva se bloquea y se notifica a la persona socia"]
    },
    {
      "id": "CA-04",
      "title": "Requisito de cancelación",
      "given": ["La persona socia puede cancelar la reserva en cualquier momento antes de recogerla"],
      "when": ["La persona socia solicita la cancelación"],
      "then": ["La reserva se anula y se libera el ejemplar"]
    }
  ],
  "business_rules": [
    {
      "id": "RN-RES-01",
      "description": "Solo pueden reservar las personas socias con carné vigente y sin sanción activa (ver RN-SAN-03 y RN-SAN-04 en DOC-03)."
    },
    {
      "id": "RN-RES-02",
      "description": "Cada persona socia puede tener un máximo de 3 reservas activas. Se considera activa la reserva en estado 'pendiente' o 'disponible para recoger'."
    },
    {
      "id": "RN-RES-03",
      "description": "La reserva se hace sobre un título y una sede de recogida. El sistema asigna el primer ejemplar de ese título que quede libre y lo traslada a la sede de recogida si es necesario."
    },
    {
      "id": "RN-RES-04",
      "description": "Las reservas de un mismo título se atienden por estricto orden de llegada (cola de reservas)."
    },
    {
      "id": "RN-RES-05",
      "description": "Cuando el ejemplar queda disponible en la sede de recogida, se bloquea durante 48 horas para la persona socia que encabeza la cola, y se le notifica (ver DOC-10)."
    },
    {
      "id": "RN-RES-06",
      "description": "Si el ejemplar no se recoge en esas 48 horas, la reserva caduca, el ejemplar pasa a la siguiente persona de la cola y la reserva cuenta como 'no recogida' a efectos de RN-SAN-04."
    },
    {
      "id": "RN-RES-07",
      "description": "La persona socia puede cancelar una reserva en cualquier momento antes de recogerla, sin penalización."
    },
    {
      "id": "RN-RES-08",
      "description": "Mientras exista una reserva pendiente sobre un título, ningún préstamo de ese título puede renovarse (artículo 5 de DOC-01)."
    },
    {
      "id": "RN-RES-09",
      "description": "No se pueden reservar obras de referencia ni títulos de los que la persona socia ya tenga un ejemplar en préstamo."
    },
    {
      "id": "RN-RES-10",
      "description": "Las personas con carné infantil pueden reservar solo títulos de la colección infantil y juvenil, con el mismo máximo de 3 reservas activas."
    }
  ],
  "assumptions": [
    "La persona socia tiene un carné vigente y sin sanción activa."
  ],
  "constraints": [
    "No se puede reservar un título si ya hay una reserva pendiente de ese título."
  ],
  "dependencies": [
    "El sistema debe poder gestionar las reservas según el Reglamento de reservas (DOC-02)."
  ],
  "alternate_flows": [
    "Si la persona socia cancela la reserva antes de recogerla, se libera el ejemplar de inmediato.",
    "Si el ejemplar no se recoge en 48 horas, se vuelve a la cola y se libera a la siguiente persona."
  ],
  "exceptions": [
    "Las reservas no recogidas reiteradas se gestionan de forma diferente (Alternativa B)"
  ],
  "related_features": [
    "La gestión de préstamo (DOC-01)",
    "La configuración de las reservas no recogidas (DOC-20)"
  ],
  "priority": "Must",
  "open_questions": [
    "¿Cómo se maneja la cancelación de reservas en caso de que el carné esté sancionado?",
    "¿Qué se hace cuando se acumulan más de 3 reservas no recogidas en un período de 90 días?"
  ]
}

